$rows=contentRows($conn,"SELECT p.name,p.price,p.duration,p.target_group,t.price_note,t.warranty_text,t.payment_note FROM products p LEFT JOIN service_terms t ON t.product_id=p.id AND t.is_active=1 WHERE COALESCE(p.is_active,1)=1 ORDER BY p.target_group,p.price,p.name");
